/**
 * German verb paradigm table and conjugation (EGS-28). Pure data and functions, no node, no dependency.
 *
 * HONESTY NOTE: the table was written by a language model and has NOT been reviewed by a native speaker. Regular verbs are generated by
 * the rules below; irregular verbs carry their principal parts by hand. `tests/de-verbs.test.ts` checks a set of forms that can be verified
 * by rule. A form the table gets wrong is a wrong lint error or a missed one: the lint says "check by hand" for verbs it does not know.
 */
import { REFLEXIVE_PRONOUNS, isDePerson, type DePerson } from './pronouns'

export type DeLevel = 'A1' | 'A2' | 'B1'
export type DeTense = 'praesens' | 'perfekt' | 'praeteritum' | 'futur1' | 'imperativ' | 'konjunktiv2'
export const DE_TENSES: readonly DeTense[] = ['praesens', 'perfekt', 'praeteritum', 'futur1', 'imperativ', 'konjunktiv2']

type Slot = 'ich' | 'du' | 'er' | 'wir' | 'ihr' | 'sie'

export interface DeVerb {
  /** The infinitive, with the separable prefix ("aufstehen"), without "sich". */
  inf: string
  aux: 'haben' | 'sein'
  /** Partizip II, whole ("aufgestanden"). */
  partizip2: string
  /** First / third person singular Präteritum of the BASE verb, without prefix ("stand"). */
  praet3: string
  /** Present forms that differ from the regular pattern: stem changes (du gibst, er gibt), modals, sein. Keyed by person slot (`sie` is also `Sie`). */
  presOverrides?: Partial<Record<Slot, string>>
  /** The separable prefix ("auf"); the verb is then written "stehe auf". */
  sep?: string
  modal?: boolean
  reflexive?: boolean
  /** First / third person Konjunktiv II when it is not "würde + infinitive" only ("wäre", "ginge"). */
  k2?: string
  /** The level at which a learner meets the verb. */
  level: DeLevel
}

// ---------------------------------------------------------------- builders

interface Opts {
  aux?: 'sein'
  ov?: DeVerb['presOverrides']
  sep?: string
  refl?: boolean
  k2?: string
  modal?: boolean
  p2?: string
  praet3?: string
}

const baseOf = (inf: string, sep?: string): string => (sep ? inf.slice(sep.length) : inf)

function stemOf(base: string): string {
  if (base.endsWith('eln') || base.endsWith('ern')) return base.slice(0, -1)
  if (base.endsWith('en')) return base.slice(0, -2)
  if (base.endsWith('n')) return base.slice(0, -1)
  return base
}

const VOWELS = 'aeiouäöüy'
/** The stem takes an extra e before -st / -t: arbeiten, finden, öffnen, rechnen, atmen (but not lernen, nehmen, kommen, wohnen). */
function needsE(stem: string): boolean {
  const last = stem.at(-1) ?? ''
  if (last === 'd' || last === 't') return true
  if (last === 'm' || last === 'n') {
    const prev = stem.at(-2) ?? ''
    if (prev === '' || VOWELS.includes(prev) || prev === 'l' || prev === 'r' || prev === last) return false
    if (prev === 'h') return stem.at(-3) === 'c'
    return true
  }
  return false
}

const sibilant = (stem: string): boolean => /[sßzx]$/.test(stem)
const INSEPARABLE = /^(be|ver|er|ent|ge|zer|emp|miss)/

function S(inf: string, level: DeLevel, partizip2: string, praet3: string, o: Opts = {}): DeVerb {
  const v: DeVerb = { inf, aux: o.aux ?? 'haben', partizip2, praet3, level }
  if (o.ov) v.presOverrides = o.ov
  if (o.sep) v.sep = o.sep
  if (o.refl) v.reflexive = true
  if (o.modal) v.modal = true
  if (o.k2) v.k2 = o.k2
  return v
}

/** A regular (weak) verb: the participle and the Präteritum are generated. */
function W(inf: string, level: DeLevel, o: Opts = {}): DeVerb {
  const base = baseOf(inf, o.sep)
  const stem = stemOf(base)
  const e = needsE(stem)
  const insep = INSEPARABLE.test(base) || /ieren$/.test(base)
  const p2 = o.p2 ?? `${o.sep ?? ''}${insep ? '' : 'ge'}${stem}${e ? 'et' : 't'}`
  return S(inf, level, p2, o.praet3 ?? `${stem}${e ? 'ete' : 'te'}`, o)
}

const E_I = (du: string, er: string): Opts['ov'] => ({ du, er })

