// ---------------------------------------------------------------- lookup

const INDEX = new Map<string, DeVerb>()
for (const v of DE_VERBS) {
  INDEX.set((v.reflexive ? 'sich ' : '') + v.inf, v)
  if (!INDEX.has(v.inf)) INDEX.set(v.inf, v)
}

/** The table entry of an infinitive ("gehen", "sich freuen", "freuen"), or undefined when the verb is not in the table. */
export function findVerb(inf: string): DeVerb | undefined {
  const k = inf.trim().toLowerCase().replace(/\s+/g, ' ')
  return INDEX.get(k) ?? INDEX.get(k.replace(/^sich /, ''))
}

// ---------------------------------------------------------------- forms

const slotOf = (p: DePerson): Slot => (p === 'Sie' ? 'sie' : p)
const WERDEN: Record<Slot, string> = { ich: 'werde', du: 'wirst', er: 'wird', wir: 'werden', ihr: 'werdet', sie: 'werden' }
const HABEN: Record<Slot, string> = { ich: 'habe', du: 'hast', er: 'hat', wir: 'haben', ihr: 'habt', sie: 'haben' }
const SEIN: Record<Slot, string> = { ich: 'bin', du: 'bist', er: 'ist', wir: 'sind', ihr: 'seid', sie: 'sind' }
const WUERDE: Record<Slot, string> = { ich: 'würde', du: 'würdest', er: 'würde', wir: 'würden', ihr: 'würdet', sie: 'würden' }
/** Verbs whose Konjunktiv II is only the special form ("würde sein" is not taught). */
const K2_ALONE = new Set(['sein', 'haben', 'werden', 'wissen', 'können', 'müssen', 'dürfen', 'sollen', 'wollen', 'mögen'])

const join = (...parts: (string | undefined | false)[]): string => parts.filter(Boolean).join(' ')

/** Finite present form of the base verb (without prefix and reflexive pronoun). */
function presFinite(v: DeVerb, slot: Slot): string {
  const base = baseOf(v.inf, v.sep)
  const ov = v.presOverrides?.[slot]
  if (ov) return ov
  const stem = stemOf(base)
  const e = needsE(stem)
  switch (slot) {
    case 'ich':
      if (base.endsWith('eln')) return `${stem.slice(0, -2)}le`
      return `${stem}e`
    case 'du':
      return sibilant(stem) ? `${stem}t` : e ? `${stem}est` : `${stem}st`
    case 'er':
    case 'ihr':
      return e ? `${stem}et` : `${stem}t`
    default:
      return base
  }
}

function praetForms(v: DeVerb, slot: Slot): string[] {
  const p = v.praet3
  if (slot === 'ich' || slot === 'er') return [p]
  if (slot === 'wir' || slot === 'sie') return [p.endsWith('e') ? `${p}n` : `${p}en`]
  if (slot === 'ihr') return [/[dt]$/.test(p) ? `${p}et` : `${p}t`]
  // du
  if (/[sßzx]$/.test(p)) return [`${p}est`, `${p}t`]
  if (/[dt]$/.test(p)) return [`${p}est`]
  return [`${p}st`]
}

function k2Forms(v: DeVerb, slot: Slot): string[] {
  const k = v.k2
  if (!k || v.sep) return []
  if (k === 'wäre' && slot === 'ihr') return ['wärt', 'wäret']
  const f = slot === 'ich' || slot === 'er' ? k : slot === 'du' ? `${k}st` : slot === 'ihr' ? `${k}t` : `${k}n`
  return [f]
}

function imperativeDu(v: DeVerb): string[] {
  if (v.modal) return []
  const base = baseOf(v.inf, v.sep)
  if (base === 'sein') return ['sei']
  if (base === 'haben') return ['hab', 'habe']
  if (base === 'werden') return ['werde']
  if (base === 'wissen') return ['wisse']
  if (base === 'tun') return ['tu', 'tue']
  const stem = stemOf(base)
  if (base.endsWith('eln')) return [`${stem.slice(0, -2)}le`]
  if (base.endsWith('ern')) return [`${stem}e`, `${stem.slice(0, -2)}re`]
  const du = v.presOverrides?.du
  let main = stem
  if (du && !/[äöü]/.test(du)) main = sibilant(stem) ? du.replace(/t$/, '') : du.replace(/st$/, '')
  return needsE(main) ? [`${main}e`, main] : [main, `${main}e`]
}

/**
 * The accepted forms of one person in one tense, canonical first, WITHOUT the pronoun and with every word the learner types:
 * compound tenses ("bin gegangen", "werde gehen"), separable prefix at the end ("stehe auf"), reflexive pronoun ("freue mich").
 * The imperative has only du, ihr and Sie ("gehen Sie"). Returns [] for a person or tense the verb does not have.
 */
export function conjugate(verb: DeVerb, tense: DeTense, person: string): string[] {
  if (!isDePerson(person)) return []
  const slot = slotOf(person)
  const refl = verb.reflexive ? REFLEXIVE_PRONOUNS[person] : undefined
  const sep = verb.sep
  switch (tense) {
    case 'praesens':
      return [join(presFinite(verb, slot), refl, sep)]
    case 'perfekt':
      return [join((verb.aux === 'sein' ? SEIN : HABEN)[slot], refl, verb.partizip2)]
    case 'praeteritum':
      return praetForms(verb, slot).map((f) => join(f, refl, sep))
    case 'futur1':
      return [join(WERDEN[slot], refl, verb.inf)]
    case 'konjunktiv2': {
      const out = k2Forms(verb, slot).map((f) => join(f, refl))
      if (!K2_ALONE.has(verb.inf)) out.push(join(WUERDE[slot], refl, verb.inf))
      return out
    }
    case 'imperativ': {
      if (verb.modal) return []
      if (person === 'du') return imperativeDu(verb).map((f) => join(f, refl, sep))
      if (person === 'ihr') return [join(presFinite(verb, 'ihr'), refl, sep)]
      if (person === 'Sie') return [join(verb.inf === 'sein' ? 'seien' : baseOf(verb.inf, sep), 'Sie', verb.reflexive && 'sich', sep)]
      return []
    }
    default:
      return []
  }
}

// ---------------------------------------------------------------- level

const LEVEL_ORDER: Record<string, number> = { A1: 1, A2: 2, B1: 3, B2: 4, C1: 5, C2: 6 }
export const levelRank = (level: string): number => LEVEL_ORDER[level] ?? 0

/** The CEFR level at which a learner meets this tense of this verb (Präteritum of non-modal strong verbs at B1, Konjunktiv II and Futur I at B1 except the common forms). */
export function tenseForCefr(verb: DeVerb | undefined, tense: DeTense): 'A1' | 'A2' | 'B1' {
  switch (tense) {
    case 'praesens':
    case 'imperativ':
      return 'A1'
    case 'perfekt':
      return 'A2'
    case 'praeteritum':
      return verb && (verb.modal || verb.inf === 'sein' || verb.inf === 'haben') ? 'A2' : 'B1'
    case 'futur1':
      return 'B1'
    case 'konjunktiv2':
      return verb?.inf === 'mögen' ? 'A1' : verb && (verb.modal || ['sein', 'haben', 'werden'].includes(verb.inf)) ? 'A2' : 'B1'
  }
}
